-- =============================================================================
-- seed_data.sql
-- NanoBio / Supabase canonical data seed
-- Generated by splitting the canonical config.sql.
--
-- Contains data operations only: reference/config rows, catalog rows,
-- dev/sandbox users and fixtures, migration backfills, storage bucket rows,
-- fixture assertions and meal-catalog source data.
--
-- IMPORTANT: destructive LOCAL/SANDBOX seed. The first seed block clears
-- auth.users (CASCADE), matching the canonical config.sql rebuild behavior.
-- Run setup.sql BEFORE this file.
-- =============================================================================

begin;
-- ---------------------------------------------------------------------------
-- 00. Destructive reset: auth data and public schema
-- ---------------------------------------------------------------------------
-- Wipes Supabase Auth users/identities/sessions and every app object in public.
-- Requires SQL Editor/postgres privileges. Flutter anon/authenticated clients
-- must never execute this script.

do $$
begin
  if to_regclass('auth.users') is not null then
    execute 'truncate table auth.users cascade';
  end if;
end $$;

insert into
    public.users (
        id,
        email,
        phone,
        full_name,
        avatar_url,
        subscription_tier,
        product_access_status,
        is_anonymous
    )
select
    au.id,
    au.email,
    coalesce(
        au.phone,
        nullif(
            au.raw_user_meta_data ->> 'phone',
            ''
        )
    ),
    coalesce(
        nullif(
            au.raw_user_meta_data ->> 'full_name',
            ''
        ),
        nullif(
            au.raw_user_meta_data ->> 'name',
            ''
        )
    ),
    nullif(
        au.raw_user_meta_data ->> 'avatar_url',
        ''
    ),
    'free',
    case
        when au.email is null
        and au.phone is null then 'guest'
        else 'free'
    end,
    au.email is null
    and au.phone is null
from auth.users au on conflict (id) do nothing;

insert into
    public.health_subjects (
        owner_user_id,
        linked_user_id,
        subject_type,
        display_name,
        relationship
    )
select u.id, u.id, 'self', coalesce(u.full_name, u.email, 'Bạn'), 'self'
from public.users u on conflict (owner_user_id)
where
    subject_type = 'self' do nothing;

insert into public.health_profiles (user_id, subject_id)
select hs.owner_user_id, hs.id
from public.health_subjects hs
where hs.subject_type = 'self'
on conflict (subject_id) do nothing;

insert into public.lifestyle_habits (user_id, subject_id)
select hs.owner_user_id, hs.id
from public.health_subjects hs
where hs.subject_type = 'self'
on conflict (subject_id) do nothing;

-- Preserve the normal-user surface for existing active admins when upgrading
-- from the previous schema. Set app_access_mode = 'admin' explicitly for an
-- admin-only account.
update public.users u
set
    app_access_mode = 'both',
    updated_at = now()
where
    u.app_access_mode = 'user'
    and exists (
        select 1
        from public.admin_user_roles aur
        where
            aur.user_id = u.id
            and aur.is_active = true
            and aur.revoked_at is null
    );

